// LogMessage selects a process-log template before formatting its arguments.
// Opaque diagnostic values and external command output are not translated.
func LogMessage(locale, english string) string {
	if locale == "zh-CN" {
		if translated, ok := processLogChinese[english]; ok {
			return translated
		}
	}
	return english
}
